        task,
        feature,
        onSelect: () => undefined,
      }),
    );
    expect(html).not.toContain('aria-label="Status age:');
  });
});

function beforeAll(fn: () => Promise<void>) {
  // no-op for static rendering tests — module is imported at top level
  fn();
